/**
 * Builds supabase/deploy/setup.sql = all migrations + the v1 seed, in order, for a NEW hosted
 * Supabase project: paste it once into Dashboard → SQL Editor → Run.
 *   npm run deploy:sql
 * (Alternative for developers: `supabase link` + `supabase db push`, then run seed.sql.)
 */
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = join(__dirname, "..");
const migDir = join(root, "supabase/migrations");
const parts = [
  "-- Kynetik Build Tracker v2 — one-shot setup for a NEW Supabase project.",
  "-- GENERATED by scripts/deploy-sql.ts — do not edit by hand. Run once, on an empty project.",
  "",
];
for (const f of readdirSync(migDir).filter((f) => f.endsWith(".sql")).sort()) {
  parts.push(`-- ════════ migration ${f} ════════`, readFileSync(join(migDir, f), "utf8"));
}
parts.push("-- ════════ seed (v1 data, spec §17) ════════", readFileSync(join(root, "supabase/seed.sql"), "utf8"));
mkdirSync(join(root, "supabase/deploy"), { recursive: true });
writeFileSync(join(root, "supabase/deploy/setup.sql"), parts.join("\n"));
console.log("Wrote supabase/deploy/setup.sql");
